const $=s=>document.querySelector(s);const icons={home:'M3 10l9-7 9 7v10H3z M9 20v-7h6v7',search:'M20 20l-5-5 M17 10a7 7 0 1 1-14 0 7 7 0 0 1 14 0',heart:'M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8',pin:'M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0 M15 10a3 3 0 1 1-6 0 3 3 0 0 1 6 0',arrow:'M5 12h14 M13 6l6 6-6 6',bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9 M10 21h4',wifi:'M2 8a16 16 0 0 1 20 0 M5 12a11 11 0 0 1 14 0 M8 16a6 6 0 0 1 8 0 M12 20h0',food:'M4 2v7h5V2 M6.5 9v13 M18 2v20 M18 2c-5 4-5 10 0 10',bed:'M2 19V7 M22 19V7 M2 15h20 M4 15v-5h16v5 M5 10V5h14v5',shield:'M12 2l9 4v6c0 6-9 10-9 10S3 18 3 12V6z M8 12l3 3 5-6',clock:'M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0 M12 6v6l4 2',wallet:'M3 5h16v4 M3 5v15h19V9H3 M17 14h2',chat:'M21 3H3v14h4v5l6-5h8z M7 8h10 M7 12h7',grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',user:'M16 6a4 4 0 1 1-8 0 4 4 0 0 1 8 0 M4 22v-3a8 8 0 0 1 16 0v3',plus:'M12 4v16 M4 12h16',phone:'M5 3l4 5-3 3c2 3 4 5 7 7l3-3 5 4c-1 6-6 3-11 0S1 5 5 3',filter:'M3 5h18 M6 12h12 M9 19h6',check:'M4 12l5 5L20 6'};const ic=n=>`<svg aria-hidden="true" viewBox="0 0 24 24"><path d="${icons[n]||icons.home}"/></svg>`;const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const money=n=>'₹'+Number(n).toLocaleString('en-IN');
const photos=['photo-1520277739336-7bf67edfa768','photo-1560448204-e02f11c3d0e2','photo-1611892440504-42a792e24d32','photo-1505693416388-ac5ce068fe85','photo-1590490360182-c33d57733427','photo-1566665797739-1674de7a421a'];const img=i=>`https://images.unsplash.com/${photos[i%photos.length]}?auto=format&fit=crop&w=900&q=85`;
const base=[{id:1,name:'The Green House',area:'Gachibowli',type:'Co-living',price:9500,beds:8,sharing:2,rating:4.8,distance:1.2,amen:['Wi-Fi','Meals','AC'],lat:17.4401,lon:78.3489},{id:2,name:'Nest Women’s Residence',area:'Madhapur',type:'Women',price:8500,beds:5,sharing:3,rating:4.9,distance:2.4,amen:['Wi-Fi','Meals','Laundry'],lat:17.4486,lon:78.3908},{id:3,name:'Urban Hive',area:'Kondapur',type:'Men',price:7200,beds:12,sharing:3,rating:4.6,distance:3.1,amen:['Wi-Fi','Meals','AC'],lat:17.4622,lon:78.3568},{id:4,name:'Olive Living',area:'Gachibowli',type:'Women',price:11000,beds:3,sharing:1,rating:4.8,distance:1.8,amen:['Wi-Fi','AC','Laundry'],lat:17.4325,lon:78.3443},{id:5,name:'The Social Stay',area:'HITEC City',type:'Co-living',price:10500,beds:6,sharing:2,rating:4.7,distance:4.2,amen:['Wi-Fi','Meals','Gym'],lat:17.4435,lon:78.3772},{id:6,name:'Maple Boys Hostel',area:'Kukatpally',type:'Men',price:6500,beds:9,sharing:4,rating:4.5,distance:6.7,amen:['Wi-Fi','Meals','Laundry'],lat:17.4849,lon:78.4138}];
let initial={saved:[],paid:false,requests:[{id:101,title:'Wi-Fi keeps disconnecting',category:'Internet',detail:'Connection drops in room 204 in the evening.',status:'In progress',reply:'Technician scheduled for this evening.'}],announcements:[{title:'Lunch is ready',body:'Fresh meals are served in the dining hall until 2:30 PM.',type:'Food ready'},{title:'A little reminder',body:'The main gate closes at 10:30 PM. Please inform the warden if you will be late.',type:'Gate timing'}],enquiries:[],listings:base,menu:{breakfast:'Idli, sambar & coconut chutney',lunch:'Rice, dal, mixed vegetable curry & curd',dinner:'Chapati, paneer curry & rice'},moveout:null,owner:null};let db;try{db=JSON.parse(localStorage.getItem('staynest-v1'))||initial}catch{db=initial}let mode='Explore',view='discover',ownerTab='Overview',filters={loc:'',type:'',max:15000,sharing:[],amen:[],sort:'recommended'},geo=false;const save=()=>localStorage.setItem('staynest-v1',JSON.stringify(db));const toast=t=>{$('#toast').textContent=t;$('#toast').classList.add('visible');setTimeout(()=>$('#toast').classList.remove('visible'),3500)};
function setMode(m){mode=m;view=m==='Explore'?'discover':m==='Tenant'?'home':'owner';render()}function nav(v){view=v;render()}
function render(){const navs=mode==='Explore'?[['discover','Explore hostels','search'],['saved','Saved places','heart'],['enquiries','My enquiries','chat']]:mode==='Tenant'?[['home','My hostel','home'],['payments','Payments','wallet'],['requests','My requests','chat']]:[['owner','Dashboard','grid'],['property','My property','home']];$('#app').innerHTML=`<header><button class="brand" onclick="setMode('Explore')" aria-label="StayNest home"><span class="brandmark">${ic('home')}</span>StayNest<span style="color:#8ba26c">.</span></button><nav class="topnav">${navs.map(([v,l])=>`<button class="${view===v?'active':''}" onclick="nav('${v}')">${l}</button>`).join('')}</nav><div class="right"><div class="mode" aria-label="Preview role">${['Explore','Tenant','Owner'].map(m=>`<button class="${m===mode?'active':''}" onclick="setMode('${m}')">${m}</button>`).join('')}</div><button class="bell" aria-label="Notifications" onclick="notifications()">${ic('bell')}</button><span class="avatar">AK</span></div></header><main class="shell">${mode==='Explore'?explore():mode==='Tenant'?tenant():owner()}<div class="footer-note"><span>StayNest · A little closer to home.</span><span class="demo"><i class="dot"></i>Interactive demo · sample properties · data saved on this device</span></div></main><nav class="bottomnav">${navs.map(([v,l,i])=>`<button class="${view===v?'active':''}" onclick="nav('${v}')">${ic(i)}${l}</button>`).join('')}<button onclick="notifications()">${ic('bell')}Updates</button></nav>`;if(mode==='Explore')renderCards()}
function explore(){if(view==='enquiries')return `<div class="pagehead"><div><div class="eyebrow">Your next chapter</div><h1>My enquiries</h1><p>Track your remote viewings and booking requests.</p></div></div><div class="panel">${db.enquiries.length?db.enquiries.map(e=>`<div class="row"><div><h3>${esc(e.hostel)}</h3><p>${esc(e.kind)} · ${esc(e.date)} · ${esc(e.name)}</p></div><span class="status">${esc(e.status)}</span></div>`).join(''):empty('No enquiries yet','Find a place you love and request a video tour.','Explore hostels',"nav('discover')")}</div>`;return `${view==='discover'?`<section class="hero"><div><div class="eyebrow">A new city. A familiar feeling.</div><h1>Find a place.<br>Feel at home.</h1><p>Discover hostels that fit your life, your budget,<br>and your kind of people.</p></div><div class="hero-art" aria-hidden="true"><div class="sun"></div><div class="house"><div class="roof"></div><div class="windows"><i></i><i></i><i></i><i></i><i></i><i></i></div></div><div class="floating"><b>✓</b> Your next home is out there.</div></div></section><form class="searchbar" onsubmit="event.preventDefault();applyFilters()"><div class="searchfield"><label for="location">${ic('pin')} Where do you want to stay?</label><input id="location" placeholder="Area or hostel in Hyderabad" value="${esc(filters.loc)}" list="areas"><datalist id="areas">${['Gachibowli','Madhapur','Kondapur','HITEC City','Kukatpally'].map(a=>`<option>${a}</option>`).join('')}</datalist></div><div class="searchfield"><label for="hosteltype">Looking for</label><select id="hosteltype"><option value="">All hostel types</option>${['Women','Men','Co-living'].map(a=>`<option ${filters.type===a?'selected':''}>${a}</option>`).join('')}</select></div><button class="btn" type="submit">${ic('search')} Find my stay</button></form>`:`<div class="pagehead"><div><div class="eyebrow">Keep your favourites close</div><h1>Saved places</h1><p>Your shortlist, all in one place.</p></div></div>`}<div class="layout"><aside class="filters"><div class="filter-head"><h3>${ic('filter')} Filters</h3><button class="textbtn" onclick="resetFilters()">Reset</button><button class="mobile-filter hide" aria-label="Toggle filters" onclick="this.closest('aside').classList.toggle('expanded')">⌄</button></div><div class="filter-group"><h4>Monthly budget</h4><input aria-label="Maximum monthly budget" id="budget" type="range" min="5000" max="20000" step="500" value="${filters.max}" oninput="filters.max=+this.value;$('#budgetlabel').textContent=money(this.value);renderCards()"><div class="between small muted"><span>₹5,000</span><b id="budgetlabel">${money(filters.max)}</b></div></div><div class="filter-group"><h4>Room sharing</h4>${[1,2,3,4].map(n=>`<label><input type="checkbox" ${filters.sharing.includes(n)?'checked':''} onchange="toggleFilter('sharing',${n},this.checked)">${n===1?'Private room':n+' sharing'}</label>`).join('')}</div><div class="filter-group"><h4>Make yourself comfortable</h4>${['Wi-Fi','Meals','AC','Laundry','Gym'].map(a=>`<label><input type="checkbox" ${filters.amen.includes(a)?'checked':''} onchange="toggleFilter('amen','${a}',this.checked)">${a==='Meals'?'Meals included':a}</label>`).join('')}</div><div class="filter-group"><button class="btn light small" onclick="nearby()">${ic('pin')} Use my location</button><p class="small muted" style="margin-top:10px">${geo?'Distances use your location.':'Sample distances from Gachibowli.'}</p></div></aside><section><div class="between results-head"><div><h2>${view==='saved'?'Your favourites':'A good stay starts here'}</h2><p id="count" class="muted"></p></div><select class="sort" aria-label="Sort hostels" onchange="filters.sort=this.value;renderCards()">${[['recommended','Recommended'],['price','Price: low to high'],['distance','Nearest first'],['rating','Highest rated']].map(([v,l])=>`<option value="${v}" ${filters.sort===v?'selected':''}>${l}</option>`).join('')}</select></div><div id="cards" class="cards"></div></section></div>`}
function empty(title,body,label,action){return `<div class="empty">${ic('search')}<h3>${title}</h3><p>${body}</p>${label?`<button class="btn light" onclick="${action}">${label}</button>`:''}</div>`}function applyFilters(){filters.loc=$('#location').value;filters.type=$('#hosteltype').value;renderCards()}function resetFilters(){filters={loc:'',type:'',max:15000,sharing:[],amen:[],sort:'recommended'};render()}function toggleFilter(k,v,on){filters[k]=on?[...filters[k],v]:filters[k].filter(x=>x!==v);renderCards()}
function renderCards(){if(!$('#cards'))return;let list=db.listings.filter(h=>(view!=='saved'||db.saved.includes(h.id))&&(!filters.loc||(h.area+' '+h.name+' Hyderabad').toLowerCase().includes(filters.loc.toLowerCase()))&&(!filters.type||h.type===filters.type)&&h.price<=filters.max&&(!filters.sharing.length||filters.sharing.includes(h.sharing))&&filters.amen.every(a=>h.amen.includes(a)));if(filters.sort==='price')list.sort((a,b)=>a.price-b.price);if(filters.sort==='distance')list.sort((a,b)=>a.distance-b.distance);if(filters.sort==='rating')list.sort((a,b)=>b.rating-a.rating);$('#count').textContent=`${list.length} sample hostels · Hyderabad${geo?' · distance from you':''}`;$('#cards').innerHTML=list.length?list.map(h=>`<article class="card"><div class="photo"><img src="${esc(h.photo||img(h.id-1))}" alt="Illustrative room for ${esc(h.name)}" loading="lazy"><span class="badge">${h.sharing===1?'Private room':h.sharing+' sharing'}</span><button class="heart ${db.saved.includes(h.id)?'saved':''}" aria-label="${db.saved.includes(h.id)?'Unsave':'Save'} ${esc(h.name)}" onclick="toggleSave(${h.id})">${ic('heart')}</button></div><div class="cardbody"><div class="between"><div class="type">${h.type==='Men'?'Men’s hostel':h.type==='Women'?'Women’s hostel':'Co-living'}</div><div class="rating"><span>★</span> ${h.rating||'New'}</div></div><h3><button style="padding:0;text-align:left" onclick="detail(${h.id})">${esc(h.name)}</button></h3><p class="address">${esc(h.area)} · ${h.distance.toFixed(1)} km away</p><div class="amenities">${h.amen.slice(0,3).map(a=>`<span>${ic(a==='Wi-Fi'?'wifi':a==='Meals'?'food':'check')}${a}</span>`).join('')}</div><div class="cardfoot"><div><div class="price">${money(h.price)} <small>/ month</small></div><div class="vacancy">${h.beds} beds available</div></div><button class="arrow" aria-label="View ${esc(h.name)}" onclick="detail(${h.id})">${ic('arrow')}</button></div></div></article>`).join(''):empty('No places match just yet','Try a wider budget or fewer filters.','Reset filters','resetFilters()')}
function toggleSave(id){db.saved=db.saved.includes(id)?db.saved.filter(x=>x!==id):[...db.saved,id];save();renderCards()}
function nearby(){if(!navigator.geolocation)return toast('Location is unavailable. Search an area instead.');toast('Requesting your location…');navigator.geolocation.getCurrentPosition(p=>{let rad=n=>n*Math.PI/180;db.listings.forEach(h=>{let a=Math.sin(rad(h.lat-p.coords.latitude)/2)**2+Math.cos(rad(p.coords.latitude))*Math.cos(rad(h.lat))*Math.sin(rad(h.lon-p.coords.longitude)/2)**2;h.distance=6371*2*Math.atan2(Math.sqrt(a),Math.sqrt(1-a))});geo=true;filters.sort='distance';filters.loc='';render();toast('Sample hostels sorted by distance from you.')},()=>toast('Location access unavailable. Enter an area to search.'),{timeout:10000})}
function modal(title,body){$('#modal').innerHTML=`<div class="modalhead"><h2>${title}</h2><button class="close" aria-label="Close dialog" onclick="$('#modal').close()">×</button></div><div class="modalbody">${body}</div>`;if(!$('#modal').open)$('#modal').showModal()}function closeModal(){$('#modal').close()}
function detail(id){let h=db.listings.find(x=>x.id===id);modal(esc(h.name),`<img class="detailphoto" src="${esc(h.photo||img(id-1))}" alt="Illustrative hostel room"><div class="between" style="margin-top:18px"><div><div class="type">${esc(h.type)} · ${esc(h.area)}</div><h2>${money(h.price)} <span class="small muted">/ month</span></h2></div><span class="status">${h.beds} beds available</span></div><div class="detailgrid"><div class="info"><small>Room type</small>${h.sharing} sharing · attached bathroom</div><div class="info"><small>Refundable deposit</small>${money(h.price)} · terms apply</div><div class="info"><small>Notice period</small>30 days before move-out</div><div class="info"><small>Gate closing time</small>10:30 PM · late entry on request</div></div><h3>Everything you need</h3><div class="amenities">${h.amen.concat(['CCTV','Drinking water','Housekeeping']).map(a=>`<span>${esc(a)}</span>`).join('')}</div><h3>A look around</h3><div class="gallery" style="margin:15px 0"><img src="${img((id+1)%6)}" alt="Illustrative shared room"><img src="${img((id+2)%6)}" alt="Illustrative room interior"></div><div class="notice">Demo listing with illustrative photos. Availability, reviews, ownership and prices are sample data, not verified accommodation offers. Electricity and deposit deductions must be confirmed before booking.</div><div class="detail-actions"><button class="btn" onclick="enquiry(${id},'Video tour')">${ic('phone')} Request video tour</button><button class="btn outline" onclick="enquiry(${id},'Booking enquiry')">Enquire about a bed</button><a class="btn light" href="https://www.google.com/maps/search/?api=1&query=${h.lat},${h.lon}" target="_blank" rel="noopener">${ic('pin')} View area map</a></div>`)}
function enquiry(id,kind){const h=db.listings.find(x=>x.id===id);modal(kind,`<p class="muted">${esc(h.name)} · ${esc(h.area)}</p><form onsubmit="submitEnquiry(event,${id},'${kind}')"><label class="field">Your name<input name="name" required maxlength="70" placeholder="Full name"></label><label class="field">Preferred date<input type="date" name="date" required min="${new Date().toISOString().slice(0,10)}"></label><label class="field">Message<textarea name="message" maxlength="500" placeholder="Tell us your move-in date or what you would like to see."></textarea></label><div class="notice">Demo request: visible in My enquiries and Owner → Enquiries on this device. No call or message is sent.</div><button class="btn">Submit demo request</button></form>`)}function submitEnquiry(e,id,kind){e.preventDefault();let f=new FormData(e.target);db.enquiries.unshift({id:Date.now(),hostel:db.listings.find(h=>h.id===id).name,name:f.get('name'),date:f.get('date'),message:f.get('message'),kind,status:'Requested'});save();closeModal();toast('Request saved. Track it in My enquiries.')}
function tenant(){let head=`<div class="pagehead"><div><div class="eyebrow">The Green House · Room 204, Bed B</div><h1>${view==='payments'?'Your payments':view==='requests'?'We’re here to help.':'Welcome home, Aravind.'}</h1><p>${view==='home'?'A little less admin. A little more living.':'Everything about your stay, in one place.'}</p></div><button class="btn outline small" onclick="contactOwner()">${ic('phone')} Contact owner</button></div>`;if(view==='requests')return head+`<div class="between" style="margin-bottom:20px"><h3>Your requests</h3><button class="btn" onclick="newRequest()">${ic('plus')} New request</button></div><div class="panel">${requestRows(false)}</div><div class="panel"><h3>Planning to move?</h3><p class="muted small">Your agreement has a 30-day notice period. Deposit settlement is subject to the owner’s review.</p>${db.moveout?`<div class="notice">Move-out notice submitted for ${esc(db.moveout)}. Awaiting owner review.</div>`:`<button class="btn light small" style="margin-top:15px" onclick="moveOut()">Submit move-out notice</button>`}</div>`;if(view==='payments')return head+rent()+`<div class="panel" style="margin-top:22px"><h3>Payment history</h3><div class="tablewrap"><table><thead><tr><th>Period</th><th>Amount</th><th>Status</th><th>Receipt</th></tr></thead><tbody>${db.paid?`<tr><td>November 2026</td><td>₹9,500</td><td><span class="status">Demo paid</span></td><td><button class="link" onclick="receipt()">View receipt</button></td></tr>`:''}<tr><td>October 2026</td><td>₹9,500</td><td><span class="status">Sample paid</span></td><td><button class="link" onclick="receipt('October')">View receipt</button></td></tr><tr><td>Security deposit</td><td>₹9,500</td><td><span class="status blue">Sample held</span></td><td>Refundable per agreement</td></tr></tbody></table></div></div>`;return head+`<div class="dashboard"><div><div class="panel"><div class="between"><h3>Noticeboard</h3><span class="badge">${db.announcements.length} updates</span></div>${db.announcements.slice(0,4).map(a=>`<div class="row"><span class="brandmark" style="background:#edf2e2;color:#6c8a58">${ic(a.type==='Food ready'?'food':'bell')}</span><div style="flex:1"><b>${esc(a.title)}</b><p>${esc(a.body)}</p></div></div>`).join('')}</div><div class="panel"><div class="between"><h3>Your requests</h3><button class="textbtn" onclick="newRequest()">+ New request</button></div>${requestRows(false)}</div></div><div>${rent()}<div class="panel" style="margin-top:22px"><div class="between"><h3>On the menu today</h3>${ic('food')}</div>${menuHTML()}</div></div></div>`}
function rent(){return `<div class="rent"><div class="eyebrow">November rent</div><div class="between"><strong>₹9,500</strong><span class="badge">${db.paid?'Demo paid':'Due 5 Nov'}</span></div><p>${db.paid?'Your simulated payment is recorded. No money was charged.':'Includes meals & Wi-Fi · Electricity billed separately'}</p><button class="btn" onclick="${db.paid?'receipt()':'pay()'}">${ic('wallet')} ${db.paid?'View demo receipt':'Pay rent'}</button></div>`}function menuHTML(){return `<div class="menu">${Object.entries(db.menu).map(([k,v],i)=>`<div class="meal">${ic('food')}<div><b>${k[0].toUpperCase()+k.slice(1)}</b><small>${esc(v)}</small><small>${['7:30 – 9:30 AM','12:30 – 2:30 PM','7:30 – 9:30 PM'][i]}</small></div></div>`).join('')}</div>`}function pay(){modal('Pay November rent',`<div class="notice">Payment simulation only. No bank account, UPI app or payment gateway is connected.</div><div class="row"><span>Monthly rent + meals</span><b>₹9,500</b></div><div class="row"><span>Convenience fee</span><b>₹0</b></div><div class="row"><h3>Total</h3><h2>₹9,500</h2></div><button class="btn" style="width:100%;margin-top:20px" onclick="db.paid=true;save();closeModal();render();toast('Demo payment recorded. No money was charged.')">Simulate successful payment</button>`)}function receipt(month='November'){modal('Demo rent receipt',`<div class="eyebrow">StayNest · sample receipt</div><h2>The Green House</h2><div class="detailgrid"><div class="info"><small>Tenant</small>Aravind · Room 204 / Bed B</div><div class="info"><small>Period</small>${month} 2026</div><div class="info"><small>Amount</small>₹9,500</div><div class="info"><small>Status</small>Simulated payment</div></div><p class="notice">This is a prototype receipt and is not proof of an actual payment.</p>`)}function contactOwner(){modal('Contact your hostel',`<h3>The Green House · Warden desk</h3><p class="muted" style="margin-top:10px">Calling will be available after the owner has registered a verified phone number.</p><div class="notice">No real owner contact is connected in this demo. You can test a tracked query instead.</div><button class="btn" onclick="newRequest()">${ic('chat')} Raise a query</button>`)}
function requestRows(ownerMode){return db.requests.length?db.requests.map(r=>`<div class="row"><div style="flex:1"><b>${esc(r.title)}</b><p>${esc(r.category)} · Room 204 · #${r.id.toString().slice(-5)}</p><p>${esc(r.detail)}</p>${r.reply?`<p style="color:#52744e">Owner: ${esc(r.reply)}</p>`:''}</div>${ownerMode?`<button class="btn light small" onclick="updateRequest(${r.id})">Update</button>`:''}<span class="status ${r.status==='Open'?'warn':r.status==='In progress'?'blue':''}">${r.status}</span></div>`).join(''):empty('All clear','You have no open requests.','','')}function newRequest(){modal('How can we help?',`<form onsubmit="submitRequest(event)"><label class="field">Category<select name="category"><option>Maintenance</option><option>Internet</option><option>Food</option><option>Housekeeping</option><option>Payment</option><option>Other</option></select></label><label class="field">Subject<input name="title" maxlength="90" required placeholder="For example, the fan is not working"></label><label class="field">Tell us more<textarea name="detail" required maxlength="800" placeholder="Add details to help the owner resolve it."></textarea></label><button class="btn">Submit request</button></form>`)}function submitRequest(e){e.preventDefault();let f=new FormData(e.target);db.requests.unshift({id:Date.now(),title:f.get('title'),category:f.get('category'),detail:f.get('detail'),status:'Open',reply:''});save();closeModal();render();toast('Request created. Visible in the owner dashboard.')}
function moveOut(){modal('Move-out notice',`<form onsubmit="event.preventDefault();db.moveout=new FormData(event.target).get('date');save();closeModal();render();toast('Notice submitted for owner review.')"><label class="field">Planned move-out date<input required type="date" name="date" min="${new Date(Date.now()+30*86400000).toISOString().slice(0,10)}"></label><p class="notice">A minimum 30-day notice is shown for this sample agreement. The deposit refund requires a final inspection and settlement.</p><button class="btn">Submit notice</button></form>`)}
function owner(){if(view==='property')return property();return `<div class="pagehead"><div><div class="eyebrow">Owner workspace · The Green House</div><h1>A good home, well managed.</h1><p>Your property, people and daily essentials.</p></div><button class="btn" onclick="announce()">${ic('plus')} Send update</button></div><div class="tabs">${['Overview','Rooms & beds','Payments','Requests','Enquiries','Food & notices'].map(t=>`<button class="${ownerTab===t?'active':''}" onclick="ownerTab='${t}';render()">${t}${t==='Requests'?' · '+db.requests.filter(r=>r.status!=='Resolved').length:''}</button>`).join('')}</div>${ownerContent()}`}
function ownerContent(){let h=db.listings[0];if(ownerTab==='Rooms & beds')return `<div class="panel"><div class="between"><div><h3>Room inventory</h3><p class="small muted">Availability changes are reflected in Explore on this device.</p></div><button class="btn light small" onclick="editBeds()">Update vacancies</button></div><div class="cards" style="margin-top:25px">${[201,202,203,204,205,206].map((r,i)=>`<div class="room"><div class="between"><h3>Room ${r}</h3><span class="badge">2 sharing</span></div><div class="beds"><div class="bed">${ic('bed')} A</div><div class="bed ${i<3?'free':''}">${ic('bed')} B</div></div><p class="small muted">Illustrative allocation · AC</p></div>`).join('')}</div><div class="notice">Listing has ${h.beds} available beds. Individual room assignments above are illustrative; a production inventory must reconcile each bed with reservations and tenant assignments.</div></div>`;if(ownerTab==='Payments')return `<div class="panel"><h3>Rent collection · November</h3><div class="tablewrap"><table><thead><tr><th>Tenant</th><th>Room / bed</th><th>Due</th><th>Status</th><th>Action</th></tr></thead><tbody><tr><td>Aravind K.</td><td>204 / B</td><td>₹9,500</td><td><span class="status ${db.paid?'':'warn'}">${db.paid?'Demo paid':'Due 5 Nov'}</span></td><td><button class="link" onclick="${db.paid?'receipt()':"rentReminder()"}">${db.paid?'Receipt':'Send reminder'}</button></td></tr></tbody></table></div><div class="notice">Payments shown here are sample records. Live collection needs a payment gateway and verified server-side payment notifications.</div></div>`;if(ownerTab==='Requests')return `<div class="panel"><h3>Tenant queries & maintenance</h3>${requestRows(true)}</div>${db.moveout?`<div class="panel"><h3>Move-out notice</h3><p>Aravind · Room 204 · requested date: ${esc(db.moveout)}</p><p class="muted small">Pending review and deposit settlement.</p></div>`:''}`;if(ownerTab==='Enquiries')return `<div class="panel"><h3>Remote tours & booking enquiries</h3>${db.enquiries.length?db.enquiries.map(e=>`<div class="row"><div><b>${esc(e.name)} · ${esc(e.hostel)}</b><p>${esc(e.kind)} · ${esc(e.date)}</p><p>${esc(e.message)}</p></div><select class="sort" aria-label="Enquiry status" onchange="changeEnquiry(${e.id},this.value)">${['Requested','Confirmed','Completed','Cancelled'].map(s=>`<option ${s===e.status?'selected':''}>${s}</option>`).join('')}</select></div>`).join(''):empty('No enquiries yet','Create a video tour request in Explore to test this flow.','','')}</div>`;if(ownerTab==='Food & notices')return `<div class="dashboard"><div class="panel"><div class="between"><h3>Today’s menu</h3><button class="textbtn" onclick="editMenu()">Edit menu</button></div>${menuHTML()}<button class="btn" style="margin-top:20px" onclick="foodReady()">${ic('food')} Notify: food is ready</button></div><div class="panel"><h3>Recent announcements</h3>${db.announcements.map(a=>`<div class="row"><div><b>${esc(a.title)}</b><p>${esc(a.body)}</p></div></div>`).join('')}</div></div>`;return `<div class="stats"><div class="stat"><span class="muted small">Available beds</span><strong>${h.beds}</strong><small>The Green House</small></div><div class="stat"><span class="muted small">Rent received</span><strong>${money(db.paid?9500:0)}</strong><small>Demo tenant · November</small></div><div class="stat"><span class="muted small">Open requests</span><strong>${db.requests.filter(r=>r.status!=='Resolved').length}</strong><small>Awaiting your attention</small></div><div class="stat"><span class="muted small">New enquiries</span><strong>${db.enquiries.filter(e=>e.status==='Requested').length}</strong><small>Tours & booking requests</small></div></div><div class="dashboard"><div><div class="panel"><div class="between"><h3>Needs your attention</h3><span class="badge">Tenant requests</span></div>${requestRows(true)}</div><div class="panel"><h3>Quick actions</h3><div class="detail-actions"><button class="btn light" onclick="editBeds()">${ic('bed')} Update vacancies</button><button class="btn light" onclick="foodReady()">${ic('food')} Food is ready</button><button class="btn light" onclick="editMenu()">Edit menu</button></div></div></div><div class="panel"><h3>Your property</h3><img src="${esc(h.photo||img(0))}" alt="Illustrative property room" style="width:100%;height:170px;object-fit:cover;border-radius:12px"><div class="row"><div><b>${esc(h.name)}</b><p>${esc(h.area)} · ${money(h.price)} / month</p></div><span class="badge">Demo</span></div><button class="btn outline" style="width:100%" onclick="nav('property')">Manage property ${ic('arrow')}</button></div></div>`}
function changeEnquiry(id,s){db.enquiries.find(e=>e.id===id).status=s;save();toast('Enquiry status updated.')}function updateRequest(id){const r=db.requests.find(r=>r.id===id);modal('Update tenant request',`<h3>${esc(r.title)}</h3><form onsubmit="saveRequest(event,${id})"><label class="field">Progress<select name="status">${['Open','In progress','Resolved'].map(s=>`<option ${r.status===s?'selected':''}>${s}</option>`).join('')}</select></label><label class="field">Update for tenant<textarea name="reply" required maxlength="800">${esc(r.reply)}</textarea></label><button class="btn">Save update</button></form>`)}function saveRequest(e,id){e.preventDefault();let f=new FormData(e.target);Object.assign(db.requests.find(r=>r.id===id),{status:f.get('status'),reply:f.get('reply')});save();closeModal();render();toast('Progress updated in tenant mode.')}
function editBeds(){modal('Update available beds',`<form onsubmit="event.preventDefault();db.listings[0].beds=+new FormData(event.target).get('beds');save();closeModal();render();toast('Vacancy updated in Explore.')"><label class="field">Available beds · The Green House<input name="beds" type="number" min="0" max="100" required value="${db.listings[0].beds}"></label><button class="btn">Save availability</button></form>`)}function announce(){modal('Send a hostel update',`<form onsubmit="submitAnnouncement(event)"><label class="field">Type<select name="type"><option>General update</option><option>Food ready</option><option>Gate timing</option><option>Maintenance</option></select></label><label class="field">Title<input name="title" required maxlength="100" placeholder="For example, dinner is ready"></label><label class="field">Message<textarea name="body" required maxlength="600"></textarea></label><div class="notice">Adds an in-app notice for the demo tenant. No SMS or background push is sent.</div><button class="btn">Post announcement</button></form>`)}function submitAnnouncement(e){e.preventDefault();let f=new FormData(e.target);db.announcements.unshift({title:f.get('title'),body:f.get('body'),type:f.get('type')});save();closeModal();render();toast('Announcement added to tenant noticeboard.')}function foodReady(){modal('Food is ready',`<form onsubmit="event.preventDefault();let meal=new FormData(event.target).get('meal');db.announcements.unshift({title:meal+' is ready',body:'Please join us in the dining hall. Enjoy your meal!',type:'Food ready'});save();closeModal();render();toast('Food-ready notice posted for tenants.')"><label class="field">Meal<select name="meal"><option>Breakfast</option><option>Lunch</option><option>Dinner</option></select></label><p class="notice">Posts a demo in-app notification. Background push delivery is not connected.</p><button class="btn">Notify tenants</button></form>`)}function rentReminder(){db.announcements.unshift({title:'Rent reminder',body:'Your November rent of ₹9,500 is due on 5 November. Please check Payments.',type:'General update'});save();toast('Reminder posted to tenant noticeboard.')}
function editMenu(){modal('Edit today’s menu',`<form onsubmit="saveMenu(event)">${Object.entries(db.menu).map(([k,v])=>`<label class="field">${k[0].toUpperCase()+k.slice(1)}<input name="${k}" value="${esc(v)}" required maxlength="200"></label>`).join('')}<button class="btn">Save menu</button></form>`)}function saveMenu(e){e.preventDefault();let f=new FormData(e.target);for(let k of Object.keys(db.menu))db.menu[k]=f.get(k);save();closeModal();render();toast('Menu updated for tenants.')}function notifications(){modal('Hostel updates',db.announcements.map(a=>`<div class="row"><div><b>${esc(a.title)}</b><p>${esc(a.body)}</p></div></div>`).join(''))}
function property(){let h=db.listings[0];return `<div class="pagehead"><div><div class="eyebrow">Owner workspace</div><h1>Your place, presented well.</h1><p>Manage listing details and owner registration.</p></div></div><div class="dashboard"><div class="panel"><h3>Listing details</h3><form onsubmit="saveProperty(event)"><label class="field">Hostel name<input name="name" value="${esc(h.name)}" required maxlength="70"></label><div class="detailgrid"><label class="field">Locality<select name="area">${['Gachibowli','Madhapur','Kondapur','HITEC City','Kukatpally'].map(a=>`<option ${a===h.area?'selected':''}>${a}</option>`).join('')}</select></label><label class="field">Hostel type<select name="type">${['Women','Men','Co-living'].map(a=>`<option ${a===h.type?'selected':''}>${a}</option>`).join('')}</select></label><label class="field">Monthly rent (₹)<input name="price" type="number" min="1000" max="100000" required value="${h.price}"></label><label class="field">Available beds<input name="beds" type="number" min="0" max="100" required value="${h.beds}"></label><label class="field">People per room<select name="sharing">${[1,2,3,4].map(n=>`<option ${n===h.sharing?'selected':''}>${n}</option>`).join('')}</select></label></div><h4>Amenities</h4><div class="amenities">${['Wi-Fi','Meals','AC','Laundry','Gym'].map(a=>`<label class="check"><input type="checkbox" name="amen" value="${a}" ${h.amen.includes(a)?'checked':''}>${a}</label>`).join('')}</div><label class="field">Room photo<input type="file" accept="image/jpeg,image/png,image/webp" onchange="uploadPhoto(this)"><span class="muted small">One room photo · maximum 1 MB · saved on this device.</span></label><button class="btn">Save listing</button></form></div><div><div class="panel"><h3>Owner registration</h3><span class="status warn">${db.owner?'Demo profile saved · unverified':'Not verified'}</span><form onsubmit="registerOwner(event)"><label class="field">Owner name<input name="name" required maxlength="70" value="${esc(db.owner?.name||'')}" placeholder="Your full name"></label><label class="field">Phone number<input name="phone" type="tel" pattern="[0-9]{10}" required value="${esc(db.owner?.phone||'')}" placeholder="10-digit mobile number"></label><label class="field">Business email<input name="email" type="email" required value="${esc(db.owner?.email||'')}"></label><label class="check small"><input type="checkbox" required> I confirm I manage this property and accept responsibility for listing accuracy.</label><div class="notice">Prototype profile only. Phone OTP, property ownership checks and admin approval must be connected before real listings go live. Do not enter identity documents here.</div><button class="btn light">Save demo profile</button></form></div><div class="panel"><h3>Before a real launch</h3><p class="small muted">Owner verification · secure tenant accounts · live bed inventory · virtual tours · booking & cancellation terms · payment gateway · deposit ledger · background notifications · moderation & support.</p></div></div></div>`}
function saveProperty(e){e.preventDefault();let f=new FormData(e.target),h=db.listings[0];Object.assign(h,{name:f.get('name'),area:f.get('area'),type:f.get('type'),price:+f.get('price'),beds:+f.get('beds'),sharing:+f.get('sharing'),amen:f.getAll('amen')});save();toast('Listing updated. Open Explore to see your changes.')}function registerOwner(e){e.preventDefault();let f=new FormData(e.target);db.owner={name:f.get('name'),phone:f.get('phone'),email:f.get('email')};save();render();toast('Demo owner profile saved. Verification is not connected.')}function uploadPhoto(input){let f=input.files[0];if(!f)return;if(!['image/jpeg','image/png','image/webp'].includes(f.type)||f.size>1048576){input.value='';return toast('Choose a JPG, PNG or WebP image under 1 MB.')}let reader=new FileReader();reader.onload=()=>{db.listings[0].photo=reader.result;try{save();toast('Photo saved to the listing.')}catch{toast('Device storage is full. Please choose a smaller image.')}};reader.readAsDataURL(f)}
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal'))closeModal()});render();
